#!/bin/sh
# Generated by cluster-manager (imagecompose). Change the recipe, not this file.
# Applies the managed server.properties keys on every start, keeps the others, then replaces the shell with the JVM.
set -eu
cd /data
cfg=/etc/dbcm/minecraft
tmp=/data/.server.properties.dbcm
if [ -f server.properties ]; then
  grep -v -E '^(server-port|motd|max-players|difficulty|view-distance|online-mode)=' server.properties > "$tmp" || true
else
  : > "$tmp"
fi
cat "$cfg/managed.properties" >> "$tmp"
mv "$tmp" server.properties
cp "$cfg/eula.txt" eula.txt
exec /usr/bin/java -Xms1G -Xmx3G -XX:+ExitOnOutOfMemoryError -Djava.io.tmpdir=/tmp -jar /opt/minecraft/server.jar nogui
